// MT2009_PLUS_SALE_TAX_V1 (db reader), server-patches/saletax: the panels' sale
// tax for the two sales the db core settles alone - a private offer the owner
// accepts and an auction's best offer. The game cores take it off a counter's
// sales themselves (SendShopBuyDBPacket); this process cannot see theirs, so
// it reads the same SALE_TAX line of the weights file the panels write, on the
// same five-second clock (playerbot_config.h). 0-50 percent; 0 or no line, no
// file - no tax.
#include <strings.h>
#include <sys/stat.h>
static int Mt2009PlusSaleTaxPercent()
{
	static time_t s_nextCheck = 0;
	static time_t s_mtime = 0;
	static long long s_size = -1;
	static int s_percent = 0;
	const time_t now = time(0);
	if (now < s_nextCheck)
		return s_percent;
	s_nextCheck = now + 5;
	const char* path = getenv("PLAYERBOT_WEIGHTS_FILE");
	if (!path || !*path)
		path = "/opt/m2spool/playerbot_weights.tsv";
	struct stat st;
	int percent = 0;
	if (stat(path, &st) == 0)
	{
		if (st.st_mtime == s_mtime && (long long) st.st_size == s_size)
			return s_percent;
		s_mtime = st.st_mtime;
		s_size = (long long) st.st_size;
		if (FILE* fp = fopen(path, "r"))
		{
			char line[256];
			while (fgets(line, sizeof(line), fp))
			{
				char key[64];
				long value = 0;
				if (sscanf(line, " %63s %ld", key, &value) == 2 && strcasecmp(key, "SALE_TAX") == 0)
					percent = value < 0 ? 0 : (value > 50 ? 50 : (int) value);
			}
			fclose(fp);
		}
	}
	else
	{
		s_mtime = 0;
		s_size = -1;
	}
	if (percent != s_percent)
		sys_log(0, "MT2009_SALE_TAX: db core - %d%% of accepted offers and auctions leaves the game", percent);
	s_percent = percent;
	return percent;
}

// What the seller keeps of an offer or an auction of `gross`.
static long long Mt2009PlusSaleTaxKeep(long long gross, const char* what, DWORD owner)
{
	const long long tax = gross > 0 ? gross * Mt2009PlusSaleTaxPercent() / 100 : 0;
	if (tax > 0)
		sys_log(0, "MT2009_SALE_TAX: %s owner %u gross %lld tax %lld", what, owner, gross, tax);
	return gross - tax;
}

